INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "耶律德光", "aliases": ["德光"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：耶律德光，守西楼、受号者。", "biography": null, "status": "draft", "id": "64c415ac-57fe-571c-8c6f-3ed68fb726da"}, {"name": "赵延寿", "aliases": ["趙延壽", "延寿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：赵延寿，公主丈夫。", "biography": null, "status": "draft", "id": "bf502cd0-4cbb-52e5-b93a-e30caa907a58"}, {"name": "耶律阮", "aliases": ["耶律兀欲", "兀欲", "永康王"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "小字兀欲，东丹王耶律倍之子。《资治通鉴》947年条下称永康王，记耶律德光将李彦绅、秦继旻的家属和财产交给他。《辽史》卷五明确名阮、小字兀欲，按同一主体建档；王号具体授封时间仍须另据后文校核，生卒年暂未录。", "biography": null, "status": "draft", "id": "42a17de5-aa28-50e6-bab8-b134f0113f3f"}, {"name": "述律平", "aliases": ["述律氏", "述律后", "述律皇后"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷269贞明二年条所见人物：述律平。", "biography": null, "status": "draft", "id": "1c865dcb-3259-50e9-b13e-181615308183"}, {"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "叶仁鲁", "aliases": ["葉仁魯"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘知远的亲将。947年率三千步骑救援承天军，在契丹兵外出劫掠时将其击败，四月丁丑收复承天军。生卒年尚未录入。", "biography": null, "status": "draft", "id": "6dacd8bb-f8c1-5bac-ab79-aa47a13e5a06"}, {"name": "何行通", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 947, "description": "契丹所任冀州刺史。947年被杀，《资治通鉴》《宋史》记冀州人杀他，《旧五代史》后文写张廷翰杀他，杀人主体存在不同记载。生年未载。", "biography": null, "status": "draft", "id": "affe3eec-865e-52de-99c5-d611237c60f4"}, {"name": "张廷翰（冀州）", "aliases": ["張廷翰（冀州）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冀州信都人，任冀州牢城指挥使。947年何行通被杀后，被推知州事；《资治通鉴》称他为符习之甥。与《宋史》另一位泽州陵川人张廷翰分别识别，生卒年尚未录入。", "biography": null, "status": "draft", "id": "e9d9bece-ce6f-57dd-b1f5-d0c32051dcd0"}, {"name": "符习", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：符习。", "biography": null, "status": "draft", "id": "054bed21-1711-5e8b-bdc8-9fe0e62d82e9"}, {"name": "李崧", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：李崧。", "biography": null, "status": "draft", "id": "42727c37-29c7-534f-b0f7-900992c16def"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

